import React, { useState } from 'react';
import { useDispatch } from 'react-redux';
import { createEvent } from '../../../features/eventOwner/eventActions'; // Adjust path as necessary

const CreateEvent = () => {
  const dispatch = useDispatch();
  const [eventData, setEventData] = useState({
    name: '',
    eventType: '',
    description: '',
    mobile: '',
    location: '',
    address: '',
    city: '',
    images: [],
    priceRange: '',
    googleGeoLocation: '',
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setEventData({ ...eventData, [name]: value });
  };

  const handleImageChange = (e) => {
    const files = Array.from(e.target.files);
    setEventData({ ...eventData, images: files });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    dispatch(createEvent(eventData));
    // Reset the form after submission
    setEventData({
      name: '',
      eventType: '',
      description: '',
      mobile: '',
      location: '',
      address: '',
      city: '',
      images: [],
      priceRange: '',
      googleGeoLocation: '',
    });
  };

  return (
    <form onSubmit={handleSubmit}>
      <h3>Create Event</h3>
      <input type="text" name="name" placeholder="Event Name" value={eventData.name} onChange={handleChange} required />
      <input type="text" name="eventType" placeholder="Event Type" value={eventData.eventType} onChange={handleChange} required />
      <textarea name="description" placeholder="Event Description" value={eventData.description} onChange={handleChange} required />
      <input type="text" name="mobile" placeholder="Mobile" value={eventData.mobile} onChange={handleChange} required />
      <input type="text" name="location" placeholder="Location" value={eventData.location} onChange={handleChange} required />
      <input type="text" name="address" placeholder="Address" value={eventData.address} onChange={handleChange} required />
      <input type="text" name="city" placeholder="City" value={eventData.city} onChange={handleChange} required />
      <input type="file" multiple onChange={handleImageChange} />
      <input type="text" name="priceRange" placeholder="Price Range" value={eventData.priceRange} onChange={handleChange} required />
      <input type="text" name="googleGeoLocation" placeholder="Google Geo Location" value={eventData.googleGeoLocation} onChange={handleChange} required />
      <button type="submit">Create Event</button>
    </form>
  );
};

export default CreateEvent;




